}

Method.Source:
/// <summary>
/// Initializes settings that are based on the released product.
/// </summary>
/// <param name = "_inventTable">An <c>InventTable</c> record buffer.</param>
public void initReleasedProductSpecificDefaulting(InventTable _inventTable)
{
    next initReleasedProductSpecificDefaulting(_inventTable);
    InventItemPurchSetup metinventItemPurchSetupStd = InventItemPurchSetup::find(purchLine.Itemid, purchLine.InventdimId);
            
    if (metinventItemPurchSetupStd.METPurchUnit)
    {
        purchLine.PurchUnit = metinventItemPurchSetupStd.METPurchUnit;
    }
}

    /// <summary>
    /// Extends the default set of mergable fields for the PurchLine table during data entity operations.
    /// </summary>
    /// <returns>
    /// A Set of field IDs (integer values) that are considered mergable.
    /// These fields will not be overwritten by preserveOriginalValues logic if they are present in the input.
    /// </returns>
    /// <remarks>
    /// This override adds PurchPrice and LineAmount to the list of mergable fields,
    /// allowing them to retain defaulted or calculated values even when input values are present.
    /// </remarks>
    public Set mergableFields()
    {
        Set result = new Set(Types::Integer);

        result = next mergableFields();

        result.add(fieldNum(PurchLine, PurchPrice));
        result.add(fieldNum(PurchLine, LineAmount));
        result.add(fieldNum(PurchLine, BarCode));
        result.add(fieldNum(PurchLine, BarcodeType));

        return result;
    }

    /// <summary>
    /// Sets the purchase status for a stocked purchase order line.
    /// </summary>
    /// <param name="_purchLineOrig">The original purchase order line which is updated.</param>
    /// <param name="_inventTransIdSum">An <c>InventTransIdSum</c> instance.</param>
    protected void setPurchStatusStocked(PurchLine _purchLineOrig, InventTransIdSum _inventTransIdSum)
    {
        InventTransIdSum inventTransIdSum = _inventTransIdSum;
        
        if(purchLine.QtyOrdered != 0 && _purchLineOrig.QtyOrdered != 0 && !purchLine.purchTable().isInterCompanyOrder())
        {
            if (purchLine.RemainPurchPhysical == 0 && purchLine.RemainPurchFinancial == 0)
            {
                if (!inventTransIdSum)
                {
                    inventTransIdSum = InventTransIdSum::newTransOriginId(
                        InventTransOriginPurchLine::findInventTransOriginId(
                            purchLine.DataAreaId, purchLine.InventTransId
                        )
                    );
                }

                if (inventTransIdSum.physical() == 0 && inventTransIdSum.financial() == 0 )
                {
                    if (this.statusChangeAllowed(purchLine, PurchStatus::Canceled))
                    {
                        purchLine.purchQty = 0;
                        purchLine.LineAmount=0;
                        purchLine.PdsCWQty = 0;
                    }
                }
            }
        }

        next setPurchStatusStocked(_purchLineOrig, _inventTransIdSum);
    }
